// Openings that still need a video: Role + ApplyUrl filled, VideoUrl empty.
const cfg = $('Company Config').first().json;
const rows = $input.all().map((i) => i.json);
if (!rows.length) return [];

// Sheets omits keys for trailing empty cells, so an all-empty VideoUrl column
// may be missing from the row objects entirely - treat missing as empty.
const val = (r, k) => String(r[k] == null ? '' : r[k]).trim();
const keys = new Set();
rows.forEach((r) => Object.keys(r).forEach((k) => keys.add(k)));
for (const required of ['Role', 'ApplyUrl']) {
  if (!keys.has(required)) {
    throw new Error('The sheet has no "' + required + '" column. Expected header row: Role, Team, Location, SalaryRange, Perk1, Perk2, Perk3, ApplyUrl, VideoUrl');
  }
}

const open = rows.filter((r) => val(r, 'Role') && val(r, 'ApplyUrl') && !val(r, 'VideoUrl'));
// Cap per run so a freshly pasted backlog cannot burn the whole balance at once.
const limit = Math.max(1, Number(cfg.maxPerRun) || 3);
return open.slice(0, limit).map((r) => ({ json: r }));

// The loop's done-output delivers every row report produced this run.
const cfg = $('Company Config').first().json;
const reports = $input.all().map((i) => i.json).filter((r) => r && r.mode);
const rendered = reports.filter((r) => r.mode === 'rendered');
const drafts = reports.filter((r) => r.mode === 'dry-run');

return [{
  json: {
    processed: reports.length,
    rendered: rendered.length,
    drafts: drafts.length,
    creditsCharged: rendered.reduce((a, r) => a + (Number(r.creditsCharged) || 0), 0),
    creditsQuoted: drafts.reduce((a, r) => a + (Number(r.creditsRequired) || 0), 0),
    rows: reports,
    nextStep: cfg.dryRun
      ? 'Open each editorLink to preview the drafts, then set dryRun to false in Company Config to render and write VideoUrl back to the sheet.'
      : 'Videos are rendered and their URLs are in the sheet. Bolt a publish tail onto "Rendered row report" (see the LinkedIn sticky note).',
  },
}];

// Builds one "We're hiring" project JSON from Company Config + one sheet row.
// Design adapted from the hr-were-hiring / hr-job-opening library examples:
// hero video + gradient shade + framed border, accent kicker pill + big role
// title, dark offer scene with numbered perk cards + salary pill, glow CTA
// scene with a circled check. Type sizes adapt to the text so long roles,
// salaries and perks never overflow their containers.
//
// This exact function is embedded in the workflow's "Build project JSON" code
// node — keep the two logically identical.

function buildProject(config, data) {
  const cfg = config || {};
  const row = data || {};

  // ---- helpers ------------------------------------------------------------
  const esc = (s) =>
    String(s == null ? '' : s).replace(/[&<>"']/g, (c) =>
      ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const clean = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
  const hex6 = (v, fb) => {
    const s = String(v == null ? '' : v).trim();
    if (/^#[0-9a-fA-F]{6}$/.test(s)) return s;
    if (/^#[0-9a-fA-F]{3}$/.test(s)) return '#' + s[1] + s[1] + s[2] + s[2] + s[3] + s[3];
    return fb;
  };
  const chan = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
  const rgba = (h, a) => { const c = chan(h); return `rgba(${c[0]},${c[1]},${c[2]},${a})`; };
  const mix = (h1, h2, t) => {
    const a = chan(h1); const b = chan(h2);
    const m = a.map((v, i) => Math.round(v + (b[i] - v) * t));
    return '#' + m.map((v) => v.toString(16).padStart(2, '0')).join('');
  };
  const isHttpUrl = (v) => /^https?:\/\//i.test(String(v == null ? '' : v).trim());

  // ---- inputs -------------------------------------------------------------
  const role = clean(row.role);
  if (!role) throw new Error(`Row ${row.rowNumber || '?'} has an empty Role — nothing to announce.`);
  const team = clean(row.team);
  const location = clean(row.location);
  const salary = clean(row.salaryRange);
  const perks = (Array.isArray(row.perks) ? row.perks : []).map(clean).filter(Boolean).slice(0, 3);
  const applyRaw = clean(row.applyUrl);
  // The URL is DISPLAYED, not clicked — show it short and readable.
  const applyDisplay = applyRaw.replace(/^https?:\/\//i, '').replace(/^www\./i, '').replace(/\/+$/, '');

  const companyName = clean(cfg.companyName) || 'YOUR COMPANY';
  const logoUrl = isHttpUrl(cfg.companyLogoUrl) ? clean(cfg.companyLogoUrl) : '';
  const kicker = clean(cfg.kicker) || "WE'RE HIRING";
  const ctaHeadline = clean(cfg.ctaHeadline) || 'Your next role is right here.';
  const ctaText = clean(cfg.ctaText) || 'Apply now';
  const font = clean(cfg.font) || 'Poppins';
  const accent = hex6(cfg.accentColor, '#FF6B57');
  const bg = hex6(cfg.backgroundColor, '#0E0F14');
  // Text that sits ON the accent (pills) uses the dark background colour.
  const ink = bg;
  const white = '#FFFFFF';
  const mutedOnDark = mix(white, bg, 0.45);
  const heroVideo = isHttpUrl(cfg.heroVideoUrl) ? clean(cfg.heroVideoUrl) : '';
  const musicUrl = isHttpUrl(cfg.musicUrl) ? clean(cfg.musicUrl) : '';

  // ---- adaptive type sizes (Poppins ~0.55em avg advance at weight 800) ----
  const roleSize =
    role.length <= 14 ? 112 :
    role.length <= 22 ? 96 :
    role.length <= 32 ? 82 :
    role.length <= 46 ? 66 :
    role.length <= 64 ? 56 : 48;
  const roleSpacing = roleSize >= 96 ? '-4px' : roleSize >= 66 ? '-2px' : '-1px';
  const salarySize = salary.length <= 14 ? 44 : salary.length <= 24 ? 38 : 32;
  const longestPerk = perks.reduce((m, p) => Math.max(m, p.length), 0);
  const perkSize = longestPerk <= 28 ? 34 : longestPerk <= 60 ? 30 : 26;
  const headlineSize = ctaHeadline.length <= 34 ? 76 : 62;
  const urlSize = applyDisplay.length <= 32 ? 28 : 24;
  const chipSize = 28;

  // ---- durations (source-example convention: transitions overlap) ---------
  const d1 = 4.0, d2 = 5.0, d3 = 4.0;
  const tDur = 0.55;

  // ---- shared brand header (logo image or company wordmark) ---------------
  const brandVisual = (dur, track) => logoUrl
    ? {
        type: 'IMAGE', src: logoUrl, x: 540, y: 110, width: 360, height: 110,
        anchor: 'top-center', resize: 'contain', track,
        enterBegin: 0.2, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: dur,
      }
    : {
        type: 'TEXT', x: 540, y: 140, anchor: 'top-center', track,
        enterBegin: 0.2, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: dur,
        style: { fontFamily: font, color: white },
        html: `<div style='color:${white}; font-size:28px; font-weight:700; letter-spacing:10px;'>${esc(companyName.toUpperCase())}</div>`,
      };

  // ---- scene 1: hook ------------------------------------------------------
  const hookVisuals = [];
  if (heroVideo) {
    hookVisuals.push({
      type: 'VIDEO', src: heroVideo, width: 1080, height: 1920,
      position: 'center-center', resize: 'cover', volume: 0, track: 0,
      enterBegin: 0, exitEnd: d1,
    });
  }
  hookVisuals.push({
    type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: d1,
    svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='whShade' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='${bg}' stop-opacity='0.72'/><stop offset='0.42' stop-color='${bg}' stop-opacity='0.15'/><stop offset='0.74' stop-color='${bg}' stop-opacity='0.4'/><stop offset='1' stop-color='${bg}' stop-opacity='0.94'/></linearGradient></defs><rect width='1080' height='1920' fill='${heroVideo ? `url(#whShade)` : bg}'/><rect x='44' y='44' width='992' height='1832' rx='44' fill='none' stroke='rgba(255,255,255,0.16)' stroke-width='1.5'/></svg>`,
  });
  hookVisuals.push(brandVisual(d1, 2));
  hookVisuals.push({
    type: 'TEXT', x: 90, y: 1140, width: 900, anchor: 'top-left', track: 3,
    enterBegin: 0.4, enterEnd: 0.9, enterAnimation: 'smoothup', exitEnd: d1,
    style: { fontFamily: font, color: white },
    html: `<div style='display:inline-block; background:${accent}; color:${ink}; border-radius:999px; padding:14px 34px; font-size:28px; font-weight:800; letter-spacing:4px;'>${esc(kicker.toUpperCase())}</div><div style='margin-top:26px; color:${white}; font-size:${roleSize}px; line-height:1.04; font-weight:800; letter-spacing:${roleSpacing};'>${esc(role)}</div>`,
  });
  const chips = [];
  if (team) chips.push(`<span style='display:inline-block; background:rgba(255,255,255,0.12); border:1.5px solid rgba(255,255,255,0.35); color:${white}; border-radius:999px; padding:12px 28px; font-size:${chipSize}px; font-weight:600; margin:0 14px 14px 0;'><span style='color:${accent};'>&#9679;</span>&nbsp; ${esc(team)}</span>`);
  if (location) chips.push(`<span style='display:inline-block; background:rgba(255,255,255,0.12); border:1.5px solid rgba(255,255,255,0.35); color:${white}; border-radius:999px; padding:12px 28px; font-size:${chipSize}px; font-weight:600; margin:0 14px 14px 0;'>${esc(location)}</span>`);
  if (chips.length) {
    hookVisuals.push({
      type: 'TEXT', x: 90, y: 1660, width: 900, anchor: 'top-left', track: 4,
      enterBegin: 0.9, enterEnd: 1.35, enterAnimation: 'smoothleft', exitEnd: d1,
      style: { fontFamily: font, color: white },
      html: `<div>${chips.join('')}</div>`,
    });
  }

  // ---- scene 2: the offer -------------------------------------------------
  const cardX = 90, cardW = 900, cardH = 200, cardStep = 240, cardBase = 620;
  const glowTop = mix(bg, accent, 0.1);
  const cardRects = perks
    .map((_, i) => `<rect x='${cardX}' y='${cardBase + i * cardStep}' width='${cardW}' height='${cardH}' rx='28' fill='rgba(255,255,255,0.05)' stroke='${rgba(accent, 0.4)}' stroke-width='1.5'/>`)
    .join('');
  const offerVisuals = [{
    type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: d2,
    svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='whOffer' cx='0.5' cy='0.28' r='0.95'><stop offset='0' stop-color='${glowTop}'/><stop offset='1' stop-color='${bg}'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#whOffer)'/>${cardRects}</svg>`,
  }];
  const teamLine = [team ? `Join the ${team} team` : '', location].filter(Boolean).join(' &middot; ');
  offerVisuals.push({
    type: 'TEXT', x: 90, y: 280, width: 900, anchor: 'top-left', track: 1,
    enterBegin: 0.25, enterEnd: 0.7, enterAnimation: 'smoothup', exitEnd: d2,
    style: { fontFamily: font, color: white },
    html: `<div style='color:${accent}; font-size:26px; font-weight:800; letter-spacing:5px;'>WHY JOIN ${esc(companyName.toUpperCase())}</div><div style='margin-top:18px; color:${white}; font-size:62px; line-height:1.06; font-weight:800; letter-spacing:-1px;'>Here&#39;s what you get.</div>${teamLine ? `<div style='margin-top:18px; color:${mutedOnDark}; font-size:30px; line-height:1.35; font-weight:500;'>${teamLine.split(' &middot; ').map(esc).join(' &middot; ')}</div>` : ''}`,
  });
  perks.forEach((perk, i) => {
    offerVisuals.push({
      type: 'TEXT', x: 130, y: cardBase + i * cardStep, width: 820, anchor: 'top-left', track: 2 + i,
      enterBegin: 0.6 + i * 0.25, enterEnd: 1.05 + i * 0.25, enterAnimation: 'smoothleft', exitEnd: d2,
      style: { fontFamily: font, color: '#E8EAF0' },
      html: `<div style='display:flex; align-items:center; height:${cardH}px;'><div style='min-width:66px; color:${accent}; font-size:40px; font-weight:800;'>0${i + 1}</div><div style='margin-left:26px; color:#E8EAF0; font-size:${perkSize}px; line-height:1.25; font-weight:600;'>${esc(perk)}</div></div>`,
    });
  });
  if (salary) {
    offerVisuals.push({
      type: 'TEXT', x: 90, y: cardBase + perks.length * cardStep + 40, anchor: 'top-left', track: 2 + perks.length,
      enterBegin: 0.85 + perks.length * 0.25, enterEnd: 1.3 + perks.length * 0.25, enterAnimation: 'smoothup', exitEnd: d2,
      // The visible glyphs sit on the accent pill — declare the accent so the
      // layout contrast lint (which reads `style`, not the inline HTML) sees
      // the element's real appearance against the dark scene.
      style: { fontFamily: font, color: accent },
      html: `<div style='color:${mutedOnDark}; font-size:24px; font-weight:700; letter-spacing:4px;'>COMPENSATION</div><div style='margin-top:16px; display:inline-block; background:${accent}; color:${ink}; border-radius:20px; padding:20px 44px; font-size:${salarySize}px; font-weight:800;'>${esc(salary)}</div>`,
    });
  }

  // ---- scene 3: CTA -------------------------------------------------------
  const ctaVisuals = [{
    type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: d3,
    svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='whGlow' cx='0.5' cy='0.4' r='0.9'><stop offset='0' stop-color='${mix(bg, accent, 0.16)}'/><stop offset='1' stop-color='${bg}'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#whGlow)'/><rect x='44' y='44' width='992' height='1832' rx='44' fill='none' stroke='${rgba(accent, 0.35)}' stroke-width='1.5'/><circle cx='540' cy='600' r='150' fill='none' stroke='${rgba(accent, 0.85)}' stroke-width='2.5'/><path d='M492 600 L528 636 L596 560' fill='none' stroke='${accent}' stroke-width='9' stroke-linecap='round' stroke-linejoin='round'/></svg>`,
  }];
  ctaVisuals.push(brandVisual(d3, 1));
  ctaVisuals.push({
    type: 'TEXT', x: 540, y: 850, width: 780, anchor: 'top-center', track: 2,
    enterBegin: 0.3, enterEnd: 0.8, enterAnimation: 'smoothup', exitEnd: d3,
    style: { fontFamily: font, color: white },
    html: `<div style='text-align:center; color:${white}; font-size:${headlineSize}px; line-height:1.06; font-weight:800; letter-spacing:-2px;'>${esc(ctaHeadline)}</div>`,
  });
  ctaVisuals.push({
    type: 'TEXT', x: 540, y: 1180, anchor: 'top-center', track: 3,
    enterBegin: 0.7, enterEnd: 1.15, enterAnimation: 'smoothup', exitEnd: d3,
    style: { fontFamily: font, color: accent },
    html: `<div style='display:inline-block; background:${accent}; color:${ink}; border-radius:999px; padding:28px 70px; font-size:42px; font-weight:800;'>${esc(ctaText)}</div>`,
  });
  if (applyDisplay) {
    ctaVisuals.push({
      type: 'TEXT', x: 540, y: 1360, width: 920, anchor: 'top-center', track: 4,
      enterBegin: 1.1, enterEnd: 1.5, enterAnimation: 'fade', exitEnd: d3,
      style: { fontFamily: font, color: mutedOnDark },
      html: `<div style='text-align:center; color:${mutedOnDark}; font-size:${urlSize}px; font-weight:600; letter-spacing:2px;'>${esc(applyDisplay)}</div>`,
    });
  }

  // ---- assemble -----------------------------------------------------------
  const slug = role.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'role';

  const payload = {
    name: `were-hiring-${slug}`,
    resolution: cfg.resolution || 'instagram-reel',
    frameRate: Number(cfg.frameRate) || 30,
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes: [
      { id: 'hook', duration: d1, backgroundColor: bg, transition: 'smoothup', transitionId: 'offer', transitionDuration: tDur, visuals: hookVisuals },
      { id: 'offer', duration: d2, backgroundColor: bg, transition: 'fade', transitionId: 'cta', transitionDuration: tDur, visuals: offerVisuals },
      { id: 'cta', duration: d3, backgroundColor: bg, visuals: ctaVisuals },
    ],
    // NOTE: no `track` on audios — the production API rejects it.
    ...(musicUrl ? { audios: [{ src: musicUrl, volume: Number(cfg.musicVolume) || 0.16 }] } : {}),
  };

  return {
    payload,
    meta: {
      rowNumber: row.rowNumber != null ? row.rowNumber : null,
      role, team, location, salary,
      perkCount: perks.length,
      applyDisplay,
      projectName: `We're hiring — ${role}`.slice(0, 120),
      nominalSeconds: d1 + d2 + d3,
    },
  };
}

// ---- n8n glue: one sheet row in, {payload, meta} out ----------------------
const cfg = $('Company Config').first().json;
const row = $json;

// Music guard: if the configured track is unreachable or over the plan's
// audio size cap, render WITHOUT music instead of failing the whole job.
let musicUrl = cfg.musicUrl;
try {
  const probe = $('Check music track').first().json;
  const status = Number(probe.statusCode);
  const headers = probe.headers || {};
  const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
  if (status !== 200 || (bytes && bytes > Number(cfg.maxMusicBytes || 5242880))) musicUrl = '';
} catch (e) { /* probe unavailable - keep the configured track */ }

const { payload, meta } = buildProject({ ...cfg, musicUrl }, {
  role: row.Role,
  team: row.Team,
  location: row.Location,
  salaryRange: row.SalaryRange,
  perks: [row.Perk1, row.Perk2, row.Perk3],
  applyUrl: row.ApplyUrl,
  rowNumber: row.row_number,
});
return [{ json: { payload, meta } }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug - surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: validated, quoted and saved as a FREE draft - nothing charged.
// One report item per row; Run summary collects them when the loop finishes.
const cfg = $('Company Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the quote.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft save failed; the report still goes out */ }

return [{
  json: {
    mode: 'dry-run',
    sheetRow: d.meta.rowNumber,
    role: d.meta.role,
    creditsRequired: d.creditsRequired,
    editorLink,
    draftId,
    warnings: d.warnings,
    videoUrl: null,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Company Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// One finished opening: the sheet now holds its video URL.
const d = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result && job.result.url) || null;

return [{
  json: {
    mode: 'rendered',
    sheetRow: d.meta.rowNumber,
    role: d.meta.role,
    creditsCharged: d.creditsRequired,
    jobId: job.id,
    videoUrl: url,
  },
}];
